"""Builds content/sources/sysdesign/problems.json (design-problem self-check data; not part of the question bank).

  python -m pipeline.sysdesign.problems_src
Estimation answers in the task strings are computed by this script (f-strings), so they cannot drift.
"""
from __future__ import annotations

import json
import math
import sys

from ..paths import ROOT

OUT = ROOT / "content" / "sources" / "sysdesign" / "problems.json"
D = 86400
P: list[dict] = []


def prob(id, title, track, difficulty, prompt, functional, nonfunc, given, tasks, rubric, outline, tradeoffs, followups, chapters, source):
    assert 8 <= len(rubric) <= 14, id
    P.append({"id": id, "title": title, "track": track, "difficulty": difficulty, "prompt": prompt,
              "requirements": {"functional": functional, "nonFunctional": nonfunc},
              "estimation": {"given": given, "tasks": tasks},
              "rubric": [{"point": a, "why": b} for a, b in rubric],
              "referenceOutline": [{"step": a, "notes": b} for a, b in outline],
              "tradeoffs": tradeoffs, "followUps": followups, "chapters": chapters, "source": source})


