def main() -> int:
    assert len(P) == 18 and len({p["id"] for p in P}) == 18
    for t in ("SYS_DESIGN", "ML_SYS_DESIGN"):
        assert sum(p["track"] == t for p in P) == (10 if t == "SYS_DESIGN" else 8)
    doc = {"version": 1, "license": "Original work of the Kairos project, derived from owner-authored study notes", "tracks": {"SYS_DESIGN": [p["id"] for p in P if p["track"] == "SYS_DESIGN"], "ML_SYS_DESIGN": [p["id"] for p in P if p["track"] == "ML_SYS_DESIGN"]}, "problems": P}
    OUT.write_text(json.dumps(doc, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    print("wrote", OUT, len(P))
    return 0


if __name__ == "__main__":
    sys.exit(main())
